package com.gameaggregator.authorizationservice.application;
import static com.gameaggregator.authorizationservice.api.AuthorizationDtos.*;import com.gameaggregator.authorizationservice.domain.AuthorizationAudit;import com.gameaggregator.authorizationservice.infrastructure.*;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AuthorizationService{private final TenantAccessClient tenants;private final AuthorizationAuditRepository audits;public AuthorizationService(TenantAccessClient t,AuthorizationAuditRepository a){tenants=t;audits=a;}@Transactional public AuthorizationDecision check(UUID user,AuthorizationRequest r,String bearer){AccessContext ctx=tenants.access(r.tenantId(),bearer);String reason=null;if(!ctx.currentUserId().equals(user))reason="USER_CONTEXT_MISMATCH";else if(!ctx.currentPermissions().contains(r.permission()))reason="MISSING_PERMISSION";else if("USER".equalsIgnoreCase(r.ownershipType())&&r.resourceOwnerId()!=null&&!r.resourceOwnerId().equals(user))reason="RESOURCE_OWNERSHIP_MISMATCH";else if("TENANT".equalsIgnoreCase(r.ownershipType())&&r.resourceOwnerId()!=null&&!r.resourceOwnerId().equals(r.tenantId()))reason="RESOURCE_TENANT_MISMATCH";else if("PRODUCTION".equalsIgnoreCase(r.environment())&&!"ACTIVE".equalsIgnoreCase(r.resourceState()))reason="RESOURCE_NOT_ACTIVE";boolean allowed=reason==null;String finalReason=allowed?"ALLOWED":reason;audits.save(new AuthorizationAudit(user,r.tenantId(),r.permission(),allowed,finalReason));return new AuthorizationDecision(allowed,finalReason,user,r.tenantId(),r.permission());}}
